-- 1120: Blog post — "DP-900 Azure Data Fundamentals in Singapore: Exam Domains, Funding and Practice Exams"
--
--       Lead-in post for WSQ - Microsoft Azure Data Fundamentals (DP-900) (TGS-2023036641).
--       Backdated to 2025-09-05 (published, status 1). No LinkedIn / Facebook share is
--       performed: linkedin_urn carries the manual-skip sentinel and the post ships
--       already-published, so publishDue never picks it up.
--
-- Every figure below was read off the LIVE course page on 2026-08-26, not invented:
--   * Fee card: full $800.00, GST $72.00 (9%), baseline nett $472.00
--     (SG/PR 21+, 50%), MCES/SME nett $312.00 (SG 40+, 70%).
--   * Course information: 2 days / 16 hrs, Beginner, 2 hrs assessment.
--   * Funding validity 18 Aug 2023 - 17 Aug 2027; Absentee Payroll $4.50/hr.
--   * Skills Framework: Data Engineering (ICT-DIT-3005-1.1).
--   * Exam weightings from the official study guide, skills measured as of 21 Jul 2026.
--   * Practice-exam URL verified HTTP 200: https://exams.tertiaryinfotech.com/practice-exams/microsoft/microsoft-dp-900
--
-- Notes for future editors:
--  * apply.php splits statements on ";" at end-of-line — the content HTML below is ONE line.
--  * Idempotent: WHERE NOT EXISTS on url_key, INSERT IGNORE on tag links. Safe to re-run.
--  * SG-only guard via @mms_instance — the CTA course is SG WSQ, absent on MY/GH.
--  * hero_image_url is NOT set here (SQL cannot render one) — generate on prod post-deploy.

SET @is_sg := IF(@mms_instance = 'SG', 1, 0);

INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `source_sku`, `meta_title`, `meta_description`, `meta_keywords`, `linkedin_urn`, `created_at`, `updated_at`) SELECT 'DP-900 Azure Data Fundamentals in Singapore: Exam Domains, Funding and Practice Exams', 'dp-900-azure-data-fundamentals-singapore-guide', 'DP-900 is the Microsoft credential for analysts, DBAs and IT staff moving from on-premise databases to Azure. This guide walks the exam domains and their weightings, sets out exactly what you pay after WSQ funding &mdash; $472 nett, or $312 for Singapore Citizens aged 40 and above &mdash; and shows what the 2 days course covers.', '<div class="mmd-summary"><div class="mmd-summary-label">Summary</div><p><strong>DP-900</strong> is the Microsoft credential for analysts, DBAs and IT staff moving from on-premise databases to Azure. This guide covers what the exam measures, what the 2 days WSQ course covers, and what you pay after SkillsFuture funding &mdash; <strong>$472</strong> for Singapore Citizens and PRs aged 21 and above, or <strong>$312</strong> for Singapore Citizens aged 40 and above.</p></div><h2>Why DP-900 is worth sitting</h2><p>Most Singapore organisations did not start on the cloud &mdash; they migrated to it, and the data layer is usually the last and hardest piece to move. DP-900 covers the concepts that make those migration conversations sensible: what relational and non-relational storage each cost you, how transactional and analytical workloads differ, and which Azure service belongs where.</p><ul><li><strong>No prerequisites.</strong> DP-900 is the entry point to the entire Azure data track.</li><li><strong>It covers both sides of the house</strong> &mdash; operational databases and analytics workloads &mdash; so it suits DBAs and reporting analysts equally.</li><li><strong>It is the prerequisite in practice for DP-100, DP-300 and DP-700</strong>, all of which assume you already know the fundamentals.</li><li><strong>The exam is only 45 minutes</strong>, making it one of the fastest Microsoft certifications to add to a CV.</li></ul><p>The course is mapped to the Skills Framework under <strong>Data Engineering</strong> (TSC code ICT-DIT-3005-1.1), and leads to roles such as Data Engineer on Azure, Azure Database Administrator, Data Scientist (using Azure tools), Business Intelligence Developer on Azure. <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-azure-data-fundamentals-dp-900.html">Check the funding you qualify for</a>.</p><h2>The DP-900 exam at a glance</h2><table><tbody><tr><td>Exam</td><td>DP-900: Microsoft Azure Data Fundamentals</td></tr><tr><td>Length</td><td>45 minutes</td></tr><tr><td>Passing score</td><td>700 out of 1000 (scaled &mdash; not 70%)</td></tr><tr><td>Prerequisites</td><td>None</td></tr><tr><td>Certification</td><td>Fundamentals certifications do not expire</td></tr></tbody></table><h2>DP-900 exam domains and weightings</h2><p>These are the skills measured on the official study guide. The weightings tell you where to spend your revision time.</p><table><thead><tr><th>Skills measured</th><th>Weighting</th></tr></thead><tbody><tr><td>Describe core data concepts</td><td>25&ndash;30%</td></tr><tr><td>Identify considerations for relational data on Azure</td><td>20&ndash;25%</td></tr><tr><td>Describe considerations for working with non-relational data on Azure</td><td>15&ndash;20%</td></tr><tr><td>Describe an analytics workload on Azure</td><td>25&ndash;30%</td></tr></tbody></table><p><em>Source: official Microsoft study guide, skills measured as of 21 Jul 2026.</em></p><h2>What the WSQ course covers</h2><p>The 2 days (16 hrs) <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-azure-data-fundamentals-dp-900.html"><strong>WSQ - Microsoft Azure Data Fundamentals (DP-900)</strong></a> course is pitched at <strong>Beginner</strong> level and is delivered in our Woodlands classroom with hands-on labs, followed by a 2 hrs assessment. The outline tracks the official objectives:</p><ol><li>Explore Core Data Concepts</li><li>Explore Relational Data in Azure</li><li>Explore Non-Relational Data in Azure</li><li>Explore Data Analytics in Azure</li></ol><h2>Practise before you book the exam</h2><p>Course participants get free, unlimited access to our <a href="https://exams.tertiaryinfotech.com/practice-exams/microsoft/microsoft-dp-900">DP-900 practice exams</a> on the Tertiary Infotech Practice Exam Portal, in both Practice Mode (with instant explanations) and timed Exam Mode. The portal offers non-participants 10 free questions per exam.</p><h2>What you actually pay: funding for DP-900 training</h2><p>The full fee is $800 before GST. As an SWDA-funded WSQ course, the subsidy depends on your citizenship, age and who is sponsoring you:</p><table><thead><tr><th>Who you are</th><th>Subsidy</th><th>You pay (incl. GST)</th></tr></thead><tbody><tr><td>Non-funded / international participants</td><td>&ndash;</td><td>$872</td></tr><tr><td>Singapore Citizen or PR, aged 21 and above</td><td>50%</td><td><strong>$472</strong></td></tr><tr><td>Singapore Citizen aged 40 and above (MCES), or SME-sponsored</td><td>70%</td><td><strong>$312</strong></td></tr></tbody></table><p><em>GST of $72 is charged at 9% on the full course fee of $800, as required for SWDA-funded courses &mdash; the subsidy applies to the course fee, not the tax.</em></p><p>Funding for this course is valid from <strong>18 Aug 2023</strong> to <strong>17 Aug 2027</strong>. You must register and complete the course within that window to qualify.</p><div class="mmd-faq"><details class="mmd-faq-item"><summary class="mmd-faq-q">1. SkillsFuture Credit (SFC)</summary><div class="mmd-faq-a"><p>Singaporeans aged 25 and above have an opening SkillsFuture Credit of $500 plus any top-ups, and those aged 40 and above received a $4,000 Mid-Career top-up. Credit can offset the fee payable after subsidy, though the Mid-Career top-up cannot be used on this course. <a href="https://www.tertiarycourses.com.sg/how-to-claim-skillsfuture-credit.html">How to claim SkillsFuture Credit</a>.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">2. SkillsFuture Enterprise Credit (SFEC)</summary><div class="mmd-faq-a"><p>Eligible employers can draw on SFEC to cover out-of-pocket costs when sponsoring staff. See our <a href="https://www.tertiarycourses.com.sg/sfec.html">SFEC guide</a> for who qualifies and how to claim.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">3. PSEA</summary><div class="mmd-faq-a"><p>Singapore Citizens can use Post-Secondary Education Account funds to offset the fee payable after subsidy. This course carries the PSEA tag, so it is eligible.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">4. UTAP</summary><div class="mmd-faq-a"><p>NTUC members can claim 50% of the unfunded fee under UTAP, capped at $250 a year, or $500 a year for members aged 40 and above. See the <a href="https://www.tertiarycourses.com.sg/utap.html">UTAP guide</a>.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">5. Absentee Payroll</summary><div class="mmd-faq-a"><p>Employers sponsoring staff can claim Absentee Payroll at $4.50 an hour, capped at $100,000 per enterprise per year, for the hours staff spend in training.</p></div></details></div><p><a href="https://www.tertiarycourses.com.sg/wsq-microsoft-azure-data-fundamentals-dp-900.html"><strong>See the live fee breakdown for your profile &rarr;</strong></a></p><h2>Your route to certification</h2><ol><li><strong>Register for the 2 days WSQ course.</strong> Pick an intake on the <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-azure-data-fundamentals-dp-900.html">course page</a> and apply your funding at checkout.</li><li><strong>Attend and complete the assessment.</strong> You need at least 75% attendance and a pass in the 2 hrs assessment to receive your WSQ Statement of Attainment.</li><li><strong>Rehearse on the practice exams</strong> until you are consistently clearing the pass mark under timed conditions.</li><li><strong>Book and sit DP-900</strong> through Pearson VUE. The certification exam is booked and paid for separately from the course.</li></ol><h2>Where to go after DP-900</h2><p>From here the path forks by role: <a href="https://www.tertiarycourses.com.sg/wsq-administering-microsoft-azure-sql-solutions-dp-300.html">DP-300</a> for database administration, <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-certified-fabric-data-engineer-associate-dp-700-training.html">DP-700</a> for data engineering on Microsoft Fabric, or <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-power-bi-data-analyst-associate-pl-300.html">PL-300</a> for analytics and reporting. Browse the full <a href="https://www.tertiarycourses.com.sg/microsoft-certifications-exams.html">Microsoft certification course catalogue</a> to plan the next rung.</p><h2>Frequently asked questions</h2><div class="mmd-faq"><details class="mmd-faq-item"><summary class="mmd-faq-q">Do I need to know SQL before taking DP-900?</summary><div class="mmd-faq-a"><p>No. The course introduces SQL concepts as part of the relational-data module. Familiarity helps, but it is not assumed.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">Is DP-900 worth it if I already work with databases?</summary><div class="mmd-faq-a"><p>Yes, if your experience is on-premise. DP-900 focuses on how those familiar concepts map onto Azure services and pricing models, which is where most experienced DBAs have gaps.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">Is the Microsoft exam fee included?</summary><div class="mmd-faq-a"><p>No. The course fee covers training and the WSQ assessment; the DP-900 exam is booked separately through Pearson VUE.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">Does this certification expire?</summary><div class="mmd-faq-a"><p>No. Microsoft fundamentals certifications, including DP-900, do not expire.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">What funding can I use?</summary><div class="mmd-faq-a"><p>Singapore Citizens and PRs aged 21 and above get 50% subsidy, rising to 70% for Citizens aged 40 and above. SkillsFuture Credit, PSEA and UTAP can offset the balance.</p></div></details></div><h2>Register for Azure Data Fundamentals training</h2><p>Seats are limited and classes fill ahead of each intake. View upcoming dates and reserve your place on the <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-azure-data-fundamentals-dp-900.html"><strong>WSQ - Microsoft Azure Data Fundamentals (DP-900)</strong></a> course page, or call us on +65 6100 0613 if you would like your funding worked out first.</p>', 'Tertiary Infotech Academy', 1, '2025-09-05', 'TGS-2023036641', 'TGS-2023036641', 'DP-900 Course Singapore | Azure Data Fundamentals | WSQ Funding', 'Train for DP-900 Azure Data Fundamentals in Singapore. 2 days WSQ course from $312 nett after funding, full exam domain breakdown, and free practice exams for participants.', 'dp-900 course singapore, azure data fundamentals certification, dp-900 exam, wsq microsoft course, skillsfuture microsoft certification, microsoft certification singapore, dp-900 funding, dp-900 training singapore', 'manual-skip-no-share', '2025-09-05 09:00:00', '2025-09-05 09:00:00' FROM DUAL WHERE @is_sg > 0 AND NOT EXISTS (SELECT 1 FROM `mmd_blog_post` WHERE `url_key` = 'dp-900-azure-data-fundamentals-singapore-guide');

