INSERT INTO `tag` (`name`, `status`) SELECT 'DP-900', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'DP-900') x);
